INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Tritt eine Änderungsanomalie nur bei nicht normalisierten Datenbanken auf?', 2, '[{"text": "Ja", "correct": true, "because": "Normalisierung verhindert Redundanzen"}, {"text": "Nein", "correct": false, "because": "Hauptursache ist fehlende Normalisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die Hauptursache für eine Änderungsanomalie?', 3, '[{"text": "Redundante Daten", "correct": true, "because": "Führt zu Inkonsistenzen bei Änderungen"}, {"text": "Fehlende Schlüssel", "correct": false, "because": "Eher Einfügeanomalie"}, {"text": "Löschvorgänge", "correct": false, "because": "Andere Anomalie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme verursacht eine Änderungsanomalie?', 5, '[{"text": "Inkonsistente Daten", "correct": true, "because": "Unterschiedliche Werte entstehen"}, {"text": "Mehrfachänderungen nötig", "correct": true, "because": "Redundanz erzwingt Anpassungen"}, {"text": "Datenverlust", "correct": false, "because": "Typisch für Lösch-Anomalie"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Änderungsanomalien entstehen durch Redundanz. b) Sie sind unvermeidbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Normalisierung vermeidet sie"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Vermeidung von Änderungsanomalien?', 4, '[{"text": "Normalisierung", "correct": false, "because": "Kern der Lösung"}, {"text": "Fremdschlüssel", "correct": false, "because": "Verhindert Inkonsistenzen"}, {"text": "Tabellenfarbe", "correct": true, "because": "Irrelevant für Datenbankdesign"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Änderungsanomalie bei einer Änderung mehrerer Datensätze auftritt?', 2, '[{"text": "Ja", "correct": true, "because": "Redundante Daten betroffen"}, {"text": "Nein", "correct": false, "because": "Typisches Szenario"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Normalform verhindert Änderungsanomalien effektiv?', 3, '[{"text": "3. Normalform", "correct": true, "because": "Eliminiert transitive Abhängigkeiten"}, {"text": "1. Normalform", "correct": false, "because": "Zu grundlegend"}, {"text": "2. Normalform", "correct": false, "because": "Nicht ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Lösung einer Änderungsanomalie?', 5, '[{"text": "Tabellenaufteilung", "correct": true, "because": "Reduziert Redundanz"}, {"text": "Fremdschlüssel", "correct": true, "because": "Zentralisiert Daten"}, {"text": "Mehr Datensätze", "correct": false, "because": "Verschärft Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Änderungsanomalien führen zu Inkonsistenzen. b) Sie betreffen nur Primärschlüssel. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Attribute betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Änderungsanomalien unwichtig?', 4, '[{"text": "Datenredundanz", "correct": false, "because": "Hauptursache"}, {"text": "Normalisierung", "correct": false, "because": "Lösungsweg"}, {"text": "Datenbankgröße", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Änderungsanomalie bei einmaligen Daten auftreten?', 2, '[{"text": "Nein", "correct": true, "because": "Redundanz nötig"}, {"text": "Ja", "correct": false, "because": "Einmalige Daten sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen hat eine Änderungsanomalie?', 4, '[{"text": "Widersprüchliche Daten", "correct": true, "because": "Inkonsistenz entsteht"}, {"text": "Manuelle Korrekturen", "correct": true, "because": "Mehr Aufwand"}, {"text": "Schnellere Abfragen", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Änderungsanomalien nur bei großen Datenbanken vorkommen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Tabellen betroffen"}, {"text": "Ja", "correct": false, "because": "Größe irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, um Änderungsanomalien zu vermeiden?', 3, '[{"text": "Normalisierung", "correct": true, "because": "Reduziert Redundanz"}, {"text": "Schnelle Updates", "correct": false, "because": "Nicht zielführend"}, {"text": "Mehr Speicher", "correct": false, "because": "Keine Lösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Änderungsanomalien entstehen bei Updates. b) Sie sind bei 3NF unvermeidbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "3NF verhindert sie"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine Änderungsanomalie?', 5, '[{"text": "Dateninkonsistenz", "correct": true, "because": "Unterschiedliche Werte"}, {"text": "Hoher Korrekturaufwand", "correct": true, "because": "Manuelle Anpassung"}, {"text": "Schnellere Datenbank", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Änderungsanomalie unwichtig?', 3, '[{"text": "Redundanz", "correct": false, "because": "Hauptursache"}, {"text": "Tabellenstruktur", "correct": false, "because": "Entscheidend"}, {"text": "Servergeschwindigkeit", "correct": true, "because": "Kein direkter Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Verhindert die 2. Normalform Änderungsanomalien vollständig?', 3, '[{"text": "Nein", "correct": true, "because": "3NF nötig für transitive Abhängigkeiten"}, {"text": "Ja", "correct": false, "because": "Nicht ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Änderungsanomalien bei Fremdschlüsseln auftreten?', 2, '[{"text": "Nein", "correct": true, "because": "Fremdschlüssel verhindern sie"}, {"text": "Ja", "correct": false, "because": "Zentralisierte Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme wähle ich gegen Änderungsanomalien?', 4, '[{"text": "Datenbanknormalisierung", "correct": true, "because": "Beseitigt Redundanz"}, {"text": "Mehr Datensätze", "correct": false, "because": "Verschlimmert Problem"}, {"text": "Schnellere Hardware", "correct": false, "because": "Keine Lösung"}]');
